from rdkit import Chem

# Parse the SMILES
smiles = "N#Cc1c(NC(=S)NC(=O)c2ccccc2)sc2c1CCCC2"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print(f"Molecule is valid")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Print atom types and connectivity
    for atom in mol.GetAtoms():
        print(f"Atom {atom.GetIdx()}: {atom.GetSymbol()}, degree={atom.GetDegree()}, aromatic={atom.GetIsAromatic()}")

    # Get ring info
    print("\nRing systems:")
    ssr = mol.GetSSSR()
    for i, ring in enumerate(ssr):
        ring_atoms = [mol.GetAtomWithIdx(idx).GetSymbol() for idx in ring]
        print(f"Ring {i+1}: {' '.join(ring_atoms)} (size {len(ring)})")

    # Look at functional groups
    print("\nFunctional groups:")
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.TRIPLE:
            print(f"Triple bond between {bond.GetBeginAtomIdx()} and {bond.GetEndAtomIdx()}")
        elif bond.GetBondType() == Chem.BondType.DOUBLE:
            a1 = bond.GetBeginAtom()
            a2 = bond.GetEndAtom()
            if a1.GetSymbol() in ['C', 'N', 'O', 'S'] and a2.GetSymbol() in ['C', 'N', 'O', 'S']:
                print(f"Double bond between {a1.GetSymbol()}({bond.GetBeginAtomIdx()}) and {a2.GetSymbol()}({bond.GetEndAtomIdx()})")

    # Check for amide/thiourea
    print("\nSearching for NC(=S)N pattern (thiourea):")
    for atom in mol.GetAtoms():
        if atom.GetSymbol() == 'N':
            neighbors = [n.GetSymbol() for n in atom.GetNeighbors()]
            if 'C' in neighbors:
                c_idx = [n.GetIdx() for n in atom.GetNeighbors() if n.GetSymbol() == 'C'][0]
                c_atom = mol.GetAtomWithIdx(c_idx)
                for nb in c_atom.GetNeighbors():
                    if nb.GetSymbol() == 'S' and c_atom.GetBondBetweenAtoms(atom.GetIdx(), nb.GetIdx()).GetBondType() == Chem.BondType.DOUBLE:
                        print(f"Found thiocarbonyl: N-{atom.GetIdx()} connected to C={nb.GetIdx()}")
                        # Check what else is connected to this carbon
                        for nnb in c_atom.GetNeighbors():
                            if nnb.GetIdx() != atom.GetIdx() and nnb.GetIdx() != nb.GetIdx():
                                print(f"  Also connected to: {nnb.GetSymbol()}({nnb.GetIdx()})")

    print("\nSearching for NC(=O)N pattern (amide/urea):")
    for atom in mol.GetAtoms():
        if atom.GetSymbol() == 'N':
            neighbors = [n.GetSymbol() for n in atom.GetNeighbors()]
            if 'C' in neighbors:
                c_idx = [n.GetIdx() for n in atom.GetNeighbors() if n.GetSymbol() == 'C'][0]
                c_atom = mol.GetAtomWithIdx(c_idx)
                for nb in c_atom.GetNeighbors():
                    if nb.GetSymbol() == 'O' and c_atom.GetBondBetweenAtoms(atom.GetIdx(), nb.GetIdx()).GetBondType() == Chem.BondType.DOUBLE:
                        print(f"Found carbonyl: N-{atom.GetIdx()} connected to C={nb.GetIdx()}")
                        for nnb in c_atom.GetNeighbors():
                            if nnb.GetIdx() != atom.GetIdx() and nnb.GetIdx() != nb.GetIdx():
                                print(f"  Also connected to: {nnb.GetSymbol()}({nnb.GetIdx()})")
else:
    print("Invalid SMILES")
EOF"}

